import{_ as t,o,c as e,a2 as l}from"./chunks/framework.DSoq407f.js";const p=JSON.parse('{"title":"授权激活","description":"","frontmatter":{},"headers":[],"relativePath":"deploy/authorization.md","filePath":"deploy/authorization.md","lastUpdated":1782304957000}'),i={name:"deploy/authorization.md"};function r(n,a,h,s,d,c){return o(),e("div",null,[...a[0]||(a[0]=[l('<h1 id="授权激活" tabindex="-1">授权激活 <a class="header-anchor" href="#授权激活" aria-label="Permalink to &quot;授权激活&quot;">​</a></h1><blockquote><p><strong>你会学到</strong>：V3 的域名授权机制、怎么激活、授权失败怎么办。</p></blockquote><h2 id="授权机制" tabindex="-1">授权机制 <a class="header-anchor" href="#授权机制" aria-label="Permalink to &quot;授权机制&quot;">​</a></h2><p>V3 是<strong>闭源商业产品</strong>，采用<strong>域名绑定授权</strong>：</p><ul><li>每个部署实例绑定到<strong>一个域名</strong>。</li><li>系统定期（约每 30 分钟）向授权云校验授权有效性。</li><li>校验通过后，本地保存一份加密缓存，断网时也能短时间正常运行。</li></ul><div class="tip custom-block"><p class="custom-block-title">为什么用域名</p><p>授权绑定到域名，而不是机器硬件。这样你换服务器、迁移部署，只要域名不变，授权就跟着走，不用重新激活。</p></div><h2 id="如何激活" tabindex="-1">如何激活 <a class="header-anchor" href="#如何激活" aria-label="Permalink to &quot;如何激活&quot;">​</a></h2><h3 id="方式一-安装时自动获取-推荐" tabindex="-1">方式一：安装时自动获取（推荐） <a class="header-anchor" href="#方式一-安装时自动获取-推荐" aria-label="Permalink to &quot;方式一：安装时自动获取（推荐）&quot;">​</a></h3><p>在 <a href="./install">安装向导</a> 里，授权码字段<strong>留空</strong>，系统会：</p><ol><li>从你访问的 Host 头提取域名。</li><li>向授权云查询该域名绑定的授权码。</li><li>自动获取并写入配置。</li></ol><p>只要你的域名已在授权平台登记，这一步全自动。</p><h3 id="方式二-手动填写" tabindex="-1">方式二：手动填写 <a class="header-anchor" href="#方式二-手动填写" aria-label="Permalink to &quot;方式二：手动填写&quot;">​</a></h3><p>如果自动获取失败（域名未登记、网络问题等），直接在安装向导的授权码字段<strong>粘贴</strong>开发商发给你的授权码字符串，重新提交即可。</p><h3 id="方式三-安装后补填" tabindex="-1">方式三：安装后补填 <a class="header-anchor" href="#方式三-安装后补填" aria-label="Permalink to &quot;方式三：安装后补填&quot;">​</a></h3><p>如果安装时没填授权码，可以编辑本地配置文件，在 <code>authorization.authcode</code> 字段填入授权码，然后重启容器。</p><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><p>激活前，确保你的<strong>部署域名已在授权平台（sq.yuafeng.cn）登记</strong>：</p><ul><li>联系开发商，把你的域名（如 <code>bot.example.com</code>）登记到授权后台。</li><li>登记后该域名会绑定一个授权码，自动获取才能成功。</li></ul><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="提示-授权验证失败-提交参数不完整" tabindex="-1">提示&quot;授权验证失败，提交参数不完整&quot; <a class="header-anchor" href="#提示-授权验证失败-提交参数不完整" aria-label="Permalink to &quot;提示&quot;授权验证失败，提交参数不完整&quot;&quot;">​</a></h3><p>通常是授权码为空且自动获取未成功。检查：</p><ul><li>域名是否已在授权平台登记。</li><li>安装向导里是否手动填了授权码。</li></ul><h3 id="提示-该授权不存在" tabindex="-1">提示&quot;该授权不存在&quot; <a class="header-anchor" href="#提示-该授权不存在" aria-label="Permalink to &quot;提示&quot;该授权不存在&quot;&quot;">​</a></h3><p>你的域名未在授权平台登记，或登记的域名与实际访问域名不一致。联系开发商核实。</p><h3 id="授权正常但后台进不去" tabindex="-1">授权正常但后台进不去 <a class="header-anchor" href="#授权正常但后台进不去" aria-label="Permalink to &quot;授权正常但后台进不去&quot;">​</a></h3><p>检查 Nginx 是否正确转发了 <code>Host</code> 头（见 <a href="./nginx#必须转发-host-头">Nginx 配置</a>）。授权靠 Host 头识别域名，转发丢了就会判定无授权。</p><h3 id="断网后还能用多久" tabindex="-1">断网后还能用多久 <a class="header-anchor" href="#断网后还能用多久" aria-label="Permalink to &quot;断网后还能用多久&quot;">​</a></h3><p>本地有加密授权缓存，断网后可短时间继续运行。网络恢复后会自动重新校验同步。</p><div class="warning custom-block"><p class="custom-block-title">不要尝试绕过授权</p><p>V3 关键模块受保护，绕过授权会导致系统无法正常运行。请通过正规渠道获取授权。</p></div><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>安装还没做 → <a href="./install">安装向导</a></li><li>配 Nginx → <a href="./nginx">Nginx 反向代理</a></li></ul>',31)])])}const q=t(i,[["render",r]]);export{p as __pageData,q as default};
